mapper.select:
SELECT DATE(create_time) as reportDate, 'summary' as reportType, COALESCE(SUM(total_amount), 0) as totalSalesAmount, COUNT(*) as totalOrderCount, COALESCE(AVG(total_amount), 0) as avgOrderAmount FROM sales_out WHERE status = 'approved'
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(create_time) ORDER BY reportDate DESC

SELECT DATE(create_time) as reportDate, 'summary' as reportType, COALESCE(SUM(total_amount), 0) as totalPurchaseAmount, COUNT(*) as totalOrderCount, COALESCE(AVG(total_amount), 0) as avgOrderAmount FROM purchase_in WHERE status = 'approved'
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(create_time) ORDER BY reportDate DESC

SELECT i.id, i.product_id as productId, p.product_name as productName, p.product_code as productCode, w.warehouse_name as warehouseName, l.location_name as locationName, i.quantity, i.min_quantity as minQuantity, i.max_quantity as maxQuantity, i.unit_price as unitPrice, i.quantity * i.unit_price as totalAmount, i.last_in_time as lastInTime, i.last_out_time as lastOutTime FROM inventory i LEFT JOIN product p ON i.product_id = p.id LEFT JOIN warehouse w ON i.warehouse_id = w.id LEFT JOIN location l ON i.location_id = l.id
AND i.warehouse_id = #{warehouseId}
AND i.product_id = #{productId}

SELECT DATE(create_time) as date, COALESCE(SUM(total_amount), 0) as amount, COUNT(*) as count FROM sales_out WHERE status = 'approved'
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(create_time) ORDER BY date ASC

SELECT DATE(create_time) as date, COALESCE(SUM(total_amount), 0) as amount, COUNT(*) as count FROM purchase_in WHERE status = 'approved'
AND DATE(create_time) BETWEEN #{startDate} AND #{endDate}
GROUP BY DATE(create_time) ORDER BY date ASC
